package com.fidecode.biteflow.application.order;import com.fidecode.biteflow.application.order.dto.MoveOrderRequest;import com.fidecode.biteflow.application.shared.port.TransactionExecutor;import com.fidecode.biteflow.domain.order.exception.BatchOrderNotFoundException;import com.fidecode.biteflow.domain.order.repository.OrderRepository;import com.fidecode.biteflow.domain.order.service.OrderDomainService;import com.fidecode.biteflow.domain.order.valueobject.OrderStatus;import com.fidecode.biteflow.domain.shared.StoreGuard;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import java.util.*;@ApplicationScoped public class BatchMoveOrdersUseCase{private final OrderRepository repo;private final OrderDomainService service;private final OrderFinalizationPublisher publisher;private final TransactionExecutor tx;@Inject public BatchMoveOrdersUseCase(OrderRepository repo, OrderDomainService service, OrderFinalizationPublisher publisher, TransactionExecutor tx){this.repo=repo;this.service=service;this.publisher=publisher;this.tx=tx;}public void execute(UUID storeId, List<String> orderIds, MoveOrderRequest request){if(orderIds==null||orderIds.isEmpty())return;tx.execute(()->{var ids=orderIds.stream().map(UUID::fromString).toList();var orders=repo.findAllById(ids);if(orders.size()!=ids.size())throw new BatchOrderNotFoundException();var target=OrderStatus.valueOf(request.targetStatus());for(var order:orders){StoreGuard.enforce(order,storeId);service.moveToColumn(order,target);var saved=repo.save(order);publisher.publishIfFinalized(saved);}return null;});}}
